from pathlib import Path
p=Path(__file__).parent/'portal-web/app.js'; s=p.read_text()
s=s.replace('<span>Deadline: ${esc(date(c.deadline))}</span>','<span>Deadline: ${esc(date(c.deadline))}</span><span>Grace: ${Math.round(c.grace_seconds/60)} minutes</span><span>Uptime checks begin: ${esc(date(c.scoring_starts_at))}</span>')
s=s.replace('Automatic service grading: ${c.auto_streak}/3 consecutive passing rounds.', 'Automatic service grading: ${c.status===\'Grace period\'?\'Grace period — no probes, availability points, or SLA deductions yet.\':`${c.auto_streak}/3 consecutive passing rounds.`}')
s=s.replace('Scheduled release: ${esc(date(c.release_at))}.', 'Scheduled release: ${c.release_at?esc(date(c.release_at)):c.release_offset!=null?`${Math.round(c.release_offset/60)} minutes after next Start`:\'Manual\'}. Grace: ${Math.round(c.grace_seconds/60)} minutes.')
s=s.replace("pill('Private organizer access'))+`<div class=\"split\">", "pill('Private organizer access'))+`<section class=\"panel\"><h2>Automatic inject releases</h2><p>${state.settings.schedule_armed_at?'Schedule armed. '+(state.settings.schedule_anchor?'Clock anchored to the event start.':'Waiting for the next Start.'):'No relative schedule armed.'} Stops do not extend release times, grace, or deadlines.</p><form id=\"schedule-form\" class=\"form-grid\"><label>Release spacing (minutes)<input name=\"spacing\" type=\"number\" value=\"30\" min=\"1\" max=\"1440\" required></label><label>Grace per task (minutes)<input name=\"grace\" type=\"number\" value=\"30\" min=\"0\" max=\"1440\" required></label><label>Event window (minutes)<input name=\"duration\" type=\"number\" value=\"240\" min=\"1\" max=\"1440\" required></label><button ${state.event?.state==='RUNNING'?'disabled':''}>Arm I01–I06 for next Start</button></form><p class=\"muted\">First task releases at Start, then each spacing interval. Unconfigured tasks remain blocked. The event window sets completion deadlines; Stop remains an organizer control.</p></section><div class=\"split\">")
s=s.replace("['create-form','announce-form','settings-form']", "['create-form','announce-form','settings-form','schedule-form']")
s=s.replace("if(e.target.id==='create-form'){", "if(e.target.id==='schedule-form'){payload={action:'schedule',codes:['I01','I02','I03','I04','I05','I06'],spacing:Number(f.spacing)*60,grace:Number(f.grace)*60,duration:Number(f.duration)*60};}else if(e.target.id==='create-form'){")
p.write_text(s,encoding='utf-8',newline='\n')
